export function normalizeStoryDate(value,year=2026){const match=String(value).match(/(?:(\d{4})[年/-])?(\d{1,2})[月/-](\d{1,2})/);if(!match)return`${year}-10-12`;return`${match[1]??year}-${match[2].padStart(2,'0')}-${match[3].padStart(2,'0')}`;}
export function inventoryFromState(state){const system=state?.系统??{},result=new Map();for(const container of [system.持有物品,system.库存,system.道具,state?.持有物品,state?.库存,state?.道具].filter(x=>x&&typeof x==='object')){const pairs=Array.isArray(container)?container.map(x=>[typeof x==='string'?x:x.name??x.名称??x.id??x.道具名,x]):Object.entries(container);for(const [key,value]of pairs){const name=String(value?.name??value?.名称??key??'').trim(),raw=typeof value==='number'?value:typeof value==='string'?1:value?.数量??value?.quantity??value?.count??1,count=Math.max(0,Math.floor(Number(raw)||0));if(!name||!count)continue;const old=result.get(name)??{name,count:0,description:''};old.count+=count;old.description||=String(value?.描述??value?.description??value?.说明??'');result.set(name,old);}}return [...result.values()];}
